int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int ret = -ENOMEM;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return ret;

    spin_lock_init(&priv->lock);
    priv->read_fifo = usb_fifo_alloc(port->serial->dev, 4096, GFP_KERNEL, &ret);
    if (!priv->read_fifo)
        goto error;

    priv->write_fifo = usb_fifo_alloc(port->serial->dev, 4096, GFP_KERNEL, &ret);
    if (!priv->write_fifo)
        goto error;

    if (port->serial->num_interrupt_in) {
        priv->packet_size = port->interrupt_out_size;
        if (!priv->packet_size)
            priv->packet_size = 64;

        if (port->serial->dev->descriptor.idVendor == 0x0403 &&
            port->serial->dev->descriptor.idProduct == 0x6001)
            priv->packet_size = 64;
    }

    priv->read_interval = port->read_urb_interval ?: 8;
    priv->write_interval = port->write_urb_interval ?: 8;

    usb_set_serial_port_data(port, priv);
    priv->drain_delay = msecs_to_jiffies(500);

    return 0;

error:
    if (priv->read_fifo)
        usb_fifo_free(priv->read_fifo, port->serial->dev);
    if (priv->write_fifo)
        usb_fifo_free(priv->write_fifo, port->serial->dev);
    kfree(priv);
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int error;

    priv = kmalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    spin_lock_init(&priv->lock);
    if (port->interrupt_out_size > 1)
        priv->packet_format = PACKET_TYPE_ISO;
    else
        priv->packet_format = PACKET_TYPE_BULK;

    priv->inflight = 0;
    priv->drain_delay = 1;

    /* Set read interval to default if not specified */
    if (!port->read_urb_size)
        port->read_urb_size = 64;

    /* Set write interval to default if not specified */
    if (!port->write_urb_size)
        port->write_urb_size = 64;

    usb_serial_set_private_data(port, priv);

    return 0;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int ret = -ENOMEM;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        goto error;

    spin_lock_init(&priv->lock);
    priv->in_buffer = usb_buffer_alloc(port->serial->dev, IN_BUFFER_SIZE, GFP_KERNEL, &priv->in_dma);
    priv->out_buffer = usb_buffer_alloc(port->serial->dev, OUT_BUFFER_SIZE, GFP_KERNEL, &priv->out_dma);
    if (!priv->in_buffer || !priv->out_buffer)
        goto error_free;

    priv->in_urb = usb_alloc_urb(0, GFP_KERNEL);
    priv->out_urb = usb_alloc_urb(0, GFP_KERNEL);
    if (!priv->in_urb || !priv->out_urb)
        goto error_free_buffers;

    usb_fill_int_urb(priv->in_urb, port->serial->dev,
                     usb_rcvintpipe(port->serial->dev, EP_IN),
                     priv->in_buffer, IN_BUFFER_SIZE,
                     cypress_read_callback, port, port->read_interval);

    usb_fill_int_urb(priv->out_urb, port->serial->dev,
                     usb_sndintpipe(port->serial->dev, EP_OUT),
                     priv->out_buffer, 0,
                     cypress_write_callback, port, port->write_interval);

    priv->packet_size = port->serial->dev->actconfig->interface[0]->altsetting[0].endpoint[0].wMaxPacketSize;

    if (is_special_device(port->serial->dev)) {
        priv->drain_delay = SPECIAL_DRAIN_DELAY;
    } else {
        priv->drain_delay = DEFAULT_DRAIN_DELAY;
    }

    port->private = priv;

    return 0;

error_free_urb:
    usb_free_urb(priv->in_urb);
    usb_free_urb(priv->out_urb);
error_free_buffers:
    usb_buffer_free(port->serial->dev, IN_BUFFER_SIZE, priv->in_buffer, priv->in_dma);
    usb_buffer_free(port->serial->dev, OUT_BUFFER_SIZE, priv->out_buffer, priv->out_dma);
error_free:
    kfree(priv);
error:
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int ret;

    priv = kmalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    mutex_init(&priv->mutex);
    ret = usb_fill_int_urb(priv->read_urb, port->serial->dev, USB_DIR_IN,
                           port->read_urb->transfer_buffer,
                           port->read_urb->transfer_buffer_length,
                           cypress_read_callback, port, port->read_interval);
    if (ret)
        goto error;

    ret = usb_fill_int_urb(priv->write_urb, port->serial->dev, USB_DIR_OUT,
                           port->write_urb->transfer_buffer,
                           port->write_urb->transfer_buffer_length,
                           cypress_write_callback, port, port->write_interval);
    if (ret)
        goto error;

    priv->drain_delay = 0; // Default drain delay
    port->private = priv;

    return 0;

error:
    kfree(priv);
    return ret;
}

int cypress_probe(struct usb_serial_port *port)
{
    struct cypress_private *priv;
    int ret;

    priv = kzalloc(sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    spin_lock_init(&priv->lock);
    ret = usb_serial_generic_open(port, NULL);
    if (ret)
        return ret;

    /* Initialize FIFO buffers */
    priv->rx_fifo = usb_buffer_alloc(port->serial->dev, FIFO_SIZE, GFP_KERNEL, NULL, 0);
    priv->tx_fifo = usb_buffer_alloc(port->serial->dev, FIFO_SIZE, GFP_KERNEL, NULL, 0);
    if (!priv->rx_fifo || !priv->tx_fifo) {
        ret = -ENOMEM;
        goto error_free_buffers;
    }

    /* Configure packet format based on interrupt output size */
    if (port->serial->interface->cur_altsetting->desc.bNumEndpoints == 2) {
        priv->packet_size = INTERRUPT_OUT_SIZE;
    } else {
        priv->packet_size = BULK_OUT_SIZE;
    }

    /* Handle special cases for certain devices */
    if (is_special_device(port)) {
        priv->read_interval = SPECIAL_READ_INTERVAL;
        priv->write_interval = SPECIAL_WRITE_INTERVAL;
    } else {
        priv->read_interval = DEFAULT_READ_INTERVAL;
        priv->write_interval = DEFAULT_WRITE_INTERVAL;
    }

    /* Associate private data with the port */
    usb_set_serial_port_data(port, priv);
    priv->drain_delay = DEFAULT_DRAIN_DELAY;

    return 0;

error_free_buffers:
    if (priv->rx_fifo)
        usb_buffer_free(port->serial->dev, FIFO_SIZE, priv->rx_fifo, 0);
    if (priv->tx_fifo)
        usb_buffer_free(port->serial->dev, FIFO_SIZE, priv->tx_fifo, 0);
    kfree(priv);
    return ret;
}
